    "definition": "Approximate Nearest Neighbor，近似最近邻搜索，用于向量召回。",
    "summary": "Approximate Nearest Neighbor，近似最近邻搜索，用于向量召回。",
    "detail": "大白话：Approximate Nearest Neighbor，近似最近邻搜索，用于向量召回。它的核心作用是把用户行为数据收集回来，并尽量判断“这个结果是不是广告带来的”。没有这些数据，系统只能看浅层点击或留资；有了它，系统才能学习哪些用户更可能转化。",
